function generate(rand, size) {
  const pick = list => list[Math.floor(rand() * list.length)];
  const leaves = [null, 0, false, '', null, 0, false, '', 1, -3, 7, 0.5, true, 'a', '0', 'false', 'null', ' '];
  const small = size === 'small', maxDepth = small ? 4 : 10;
  // budget caps the number of values; a large case retries with fewer values until its JSON fits.
  for (let budget = small ? 14 : 1100; ; budget -= 100) {
    let left = budget;
    const container = (depth, length) => {
      const items = [];
      for (let i = 0; i < length && left > 0; i++) {
        left--;
        const nested = depth < maxDepth && rand() < (small ? 0.3 : 0.45);
        items.push(nested ? container(depth + 1, Math.floor(rand() * (small ? 5 : 8))) : pick(leaves));
      }
      if (rand() < 0.5) return items;
      return Object.fromEntries(items.map((item, i) => [pick(['a', 'b', 'c', 'x', 'id', 'n']) + i, item]));
    };
    const obj = container(1, small ? Math.floor(rand() * 5) : 2000);
    if (JSON.stringify(obj).length <= 10000) return [obj];
  }
}
